const API_KEY = 'Fas1saFLobr2431r6YJGLRENvrLRLQOD';
const BASE_URL = 'http://127.0.0.1:8108';

async function test() {
  // Create a test collection
  const schema = {
    name: 'test_products',
    fields: [
      { name: 'title', type: 'string' },
      { name: 'price', type: 'float' },
      { name: 'rating', type: 'int32', optional: true }
    ]
  };

  // Delete if exists
  try {
    await fetch(`${BASE_URL}/collections/test_products`, {
      method: 'DELETE',
      headers: { 'X-TYPESENSE-API-KEY': API_KEY }
    });
  } catch (e) {}

  const createRes = await fetch(`${BASE_URL}/collections`, {
    method: 'POST',
    headers: {
      'X-TYPESENSE-API-KEY': API_KEY,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(schema)
  });
  console.log('Create status:', createRes.status);
  console.log('Create body:', await createRes.json());

  // Import some documents
  const docs = [
    '{"id":"p1","title":"Wireless Mouse","price":29.99,"rating":4}',
    '{"id":"p2","title":"Mechanical Keyboard","price":"89.99","rating":5}', // dirty price (string)
    '{"id":"p3","title":"USB-C Cable","price":9.5,"rating":"3"}', // dirty rating (string)
    '{"id":"p5","title":"Broken Widget","price":"free","rating":2}' // invalid price (cannot coerce)
  ].join('\n');

  const importRes = await fetch(`${BASE_URL}/collections/test_products/documents/import?dirty_values=coerce_or_reject`, {
    method: 'POST',
    headers: {
      'X-TYPESENSE-API-KEY': API_KEY,
      'Content-Type': 'text/plain'
    },
    body: docs
  });

  console.log('Import status:', importRes.status);
  const importText = await importRes.text();
  console.log('Import body:\n', importText);
}

test();

